/// <summary>
/// MPJ_2864 - kscerri - 17/03/2021
/// Fills in the cust account num
/// </summary>
/// <param name="sender">Form Data Source</param>
/// <param name="e">Form data source event</param>
[
    FormDataSourceEventHandler(formDataSourceStr(CustTable, METCustTable), FormDataSourceEventType::ValidatingWrite),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
]
public static void METCustTable_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 form            = sender.formRun();
    FormDataSource          custTable_ds    = form.dataSource(formDataSourceStr(CustTable,CustTable)) as FormDataSource;
    FormDataSource          metCustTable_ds = form.dataSource(formDataSourceStr(CustTable,METCustTable)) as FormDataSource;
    METCustTable            METCustTable    = metCustTable_ds.cursor();
    CustTable               CustTable       = custTable_ds.cursor();
    
    METCustTable.AccountNum = CustTable.AccountNum;
}

    /// <summary>
    /// MPJ_8105 - kscerri - 01-07-2021
    /// Generates lookup depending on legal entity field
    /// </summary>
    /// <param name="sender">form control</param>
    /// <param name="e">form events</param>
    [
        FormControlEventHandler(formControlStr(CustTable, METCustTable_CSAccountNum), FormControlEventType::Lookup),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
    ]
    public static void METCustTable_CustAccNum_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        Query				 query = new Query();
        QueryBuildDataSource qbdsCustTable, qbdsDirParty;
        SysTableLookup	     sysTableLookup;
        FormRun              formRun = sender.formRun();
        FormControl          purposeCtrl   = formRun.design().controlName(formControlStr(CustTable, METCustTable_CSLegalEntity));
        
        if (purposeCtrl.valueStr())
        {
            sysTableLookup = SysTableLookup::newParameters(tableNum(CustTable),sender,true);
            sysTableLookup.parmUseLookupValue(false);
            sysTableLookup.addLookupfield(fieldNum(CustTable, AccountNum));
            sysTableLookup.addLookupfield(fieldNum(CustTable, party), false);
            sysTableLookup.setLabel("@SYS177436");

            qbdsCustTable = query.addDataSource(tableNum(CustTable));
            qbdsCustTable.company(purposeCtrl.valueStr());

            qbdsDirParty = qbdsCustTable.addDataSource(tableNum(DirPartyTable));
            qbdsDirParty.company(purposeCtrl.valueStr());
            qbdsDirParty.joinMode(JoinMode::InnerJoin);
            qbdsDirParty.addLink(fieldNum(CustTable,Party),fieldNum(DirPartyTable,RecId));

            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }
        else
        {
            throw warning("@MET:CustAccNumLEValidation");
        }
        
        FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
        ce.CancelSuperCall();
    }

    /// <summary>
    /// MPJ_8105 - kscerri - 02-07-2021
    /// Generates lookup depending on legal entity field
    /// </summary>
    /// <param name="sender">form control</param>
    /// <param name="e">form events</param>
    [
        FormControlEventHandler(formControlStr(CustTable, METCustTable_CSLegalEntity), FormControlEventType::Lookup),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
    ]
    public static void METCustTable_LegalEntity_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        Query				 query = new Query();
        QueryBuildDataSource queryBuildDataSource;
        SysTableLookup	     sysTableLookup;

        sysTableLookup = SysTableLookup::newParameters(tableNum(companyinfo),sender,true);
        sysTableLookup.parmUseLookupValue(false);
        sysTableLookup.addLookupfield(fieldNum(companyinfo, DataArea));
        sysTableLookup.addLookupfield(fieldNum(companyinfo, Name));

        queryBuildDataSource = query.addDataSource(tableNum(companyinfo));
        queryBuildDataSource.addSortField(fieldnum(companyinfo, DataArea));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();

        FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
        ce.CancelSuperCall();
    }

