    /// <summary>
    /// MPJ_26957_AllowBackOrders
    /// Activate the customer header level allowback order based on cust parameter
    /// </summary>
    /// <param name="sender">Form Data source</param>
    /// <param name="e">Form data source event</param>
    [FormDataSourceEventHandler(formDataSourceStr(CustTable, METCustTable), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
    public static void METCustTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        METCustTable    metCustTable      = sender.cursor();

        sender.object(fieldNum(METCustTable, eStatementFormat)).enabled(metCustTable.eStatement);
        sender.object(fieldNum(METCustTable, eStatementStartDate)).enabled(metCustTable.eStatement);
        
        // Code comment to handle in future
        // CB236_IndustryKeyFieldsCheck
        //sender.object(fieldNum(METCustTable, PickEaches)).enabled(METIndustryKeyTable::find(metCustTable.IndustryKey).PickEaches);
    }

    /// <summary>
    /// MPJ_20036 OES v2
    /// </summary>
    /// <param name="sender">Form Data source</param>
    /// <param name="e">Form data source event</param>
    [FormDataFieldEventHandler(formDataFieldStr(CustTable, METCustTable, IndustryKey), FormDataFieldEventType::Modified)]
    public static void IndustryKey_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource  metCustTable_ds   = sender.datasource();
        METCustTable    metCustTable      = metCustTable_ds.cursor();

        metCustTable.PickEaches = NoYes::No;
        //metCustTable_ds.object(fieldNum(METCustTable, PickEaches)).enabled(METIndustryKeyTable::find(metCustTable.IndustryKey).PickEaches);
    }

    /// <summary>
    /// MPJ_18908 Customer MDR custom fields
    /// </summary>
    /// <param name="sender">Form Data source</param>
    /// <param name="e">Form data source event</param>
    [FormDataFieldEventHandler(formDataFieldStr(CustTable, METCustTable, eStatement), FormDataFieldEventType::Modified)]
    public static void eStatement_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource  metCustTable_ds   = sender.datasource();
        METCustTable    metCustTable      = metCustTable_ds.cursor();

        metCustTable_ds.object(fieldNum(METCustTable, eStatementFormat)).enabled(metCustTable.eStatement);
        metCustTable_ds.object(fieldNum(METCustTable, eStatementStartDate)).enabled(metCustTable.eStatement);

        metCustTable.eStatementFormat = metCustTable.eStatement ? metCustTable.eStatementFormat : METeStatementFormat::NotImplemented;
    }

    /// <summary>
    /// MPJ_34538 - Message for users where the Unsettle transactions option will pop-up with a message for Customers with status Closed
    /// </summary>
    /// <param name="sender">Form Control details associated with the Form DataSource </param>
    /// <param name="e">Form control event arguments</param>
    [FormControlEventHandler(formControlStr(CustTable, mibCustOpenTransReverse), FormControlEventType::Clicked)]
    public static void mibCustOpenTransReverse_OnClicked(FormControl sender, FormControlEventArgs e)
    {
        CustTable                   custTable;
        FormRun                     formRun = sender.formRun() as FormRun;
    
        custTable = sender.formRun().dataSource(1).cursor();

        if(custTable.CredManAccountStatusId == "@MET:Csd")
        {
            throw warning("@MET:ClosedAccountsSettle");
        }

    }

    /// <summary>
    ///  Method to determine the behaviour of certain fields based on modification of eInvioce checkbox.
    /// </summary>
    /// <param name="sender">Object of type FormDataObject</param>
    /// <param name="e">Object of type FormDataFieldEventArgs</param>
    [FormDataFieldEventHandler(formDataFieldStr(CustTable, CustTable, EInvoice), FormDataFieldEventType::Modified)]
    public static void EInvoice_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun formRun = sender.datasource().formRun();
        CustTable custTable = formRun.dataSource(formDataSourceStr(CustTable, CustTable)).cursor();

        FormDataSource metCustTableDS = formRun.dataSource(formDataSourceStr(CustTable, METCustTable));
        metCustTableDS.object(fieldNum(METCustTable, eInvoiceVersionId)).allowEdit(custTable.EInvoice);

        if (custTable.EInvoice)
        {    
            METCustTable metCustTable = metCustTableDS.cursor();

            if (!metCustTable.eInvoiceVersionId && metCustTable.IndustryKey)
            {
                metCustTable.eInvoiceVersionId = METIndustryKeyTable::find(metCustTable.IndustryKey).EInvoiceVersionId;
            }
        }
    }
